using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<WebSearchTool>();
builder.Services.AddSingleton<NoteTakingTool>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearch = host.Services.GetRequiredService<WebSearchTool>();
var noteTaking = host.Services.GetRequiredService<NoteTakingTool>();

// Configure the agent with tools
var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the web_search tool
        2. Taking notes on key findings using the take_note tool
        3. Performing multiple searches to cover different aspects of the topic
        4. Finally, producing a comprehensive summary of your research findings

        Always search for at least 3 different aspects of the topic before summarizing.
        Use the note-taking tool to record important facts as you find them.
        End your response with a clear, well-structured summary.
        """,
    Tools = [webSearch.AsAIFunction(), noteTaking.AsAIFunction()],
    MaximumIterations = 10,
});

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('-', 50));

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(messages, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('-', 50));
Console.WriteLine("\nResearch Notes Collected:");
foreach (var note in noteTaking.GetNotes())
{
    Console.WriteLine($"  • {note}");
}

