using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    [Description("Searches the web for information on a given query and returns relevant results.")]
    public AIFunction AsAIFunction() => AIFunctionFactory.Create(SearchWebAsync, new AIFunctionFactoryOptions
    {
        Name = "web_search",
        Description = "Searches the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.",
    });

    [Description("Searches the web for information on a given query.")]
    private static async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Use a public search API (DuckDuckGo Instant Answer API)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await HttpClient.GetAsync(url, cancellationToken);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);

            var results = new List<string>();

            // Extract abstract
            var abstractText = json.GetProperty("Abstract").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}");
            }

            // Extract related topics
            if (json.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var topicText = text.GetString();
                        if (!string.IsNullOrWhiteSpace(topicText))
                        {
                            results.Add(topicText);
                        }
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"Search for '{query}' returned no structured results. The topic may require more specific queries.";
            }

            return $"Search results for '{query}':\n" + string.Join("\n---\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class NoteTakingTool
{
    private readonly List<string> _notes = [];
    private readonly Lock _lock = new();

    [Description("Takes a note to remember an important finding during research.")]
    public AIFunction AsAIFunction() => AIFunctionFactory.Create(TakeNote, new AIFunctionFactoryOptions
    {
        Name = "take_note",
        Description = "Records a research note. Use this to save key facts, findings, or insights discovered during research. Notes are accumulated and presented at the end.",
    });

    [Description("Records a research note about an important finding.")]
    private string TakeNote(
        [Description("The note content to record — a key fact, finding, or insight")] string note,
        [Description("Optional category for the note (e.g., 'definition', 'statistic', 'opinion', 'source')")] string? category = null)
    {
        var formattedNote = string.IsNullOrWhiteSpace(category)
            ? note
            : $"[{category}] {note}";

        lock (_lock)
        {
            _notes.Add(formattedNote);
        }

        return $"Note #{_notes.Count} recorded: {formattedNote}";
    }

    public IReadOnlyList<string> GetNotes()
    {
        lock (_lock)
        {
            return [.. _notes];
        }
    }
}

